use std::io;
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use common_file_actions::{
    CLOCK_TICKS, ScenarioBin, canceled_error, fixture_paths, journal_path, pattern_bytes, stamp,
};
use pr_core::abstractions::{AppendStream, Clock, FileStat, FileSystem, ReadSeek, RecycleBin};
use pr_core::catalog::types::CaptureGroup;
use pr_core::file_actions::journal::{OperationJournal, OperationJournalOptions};
use pr_core::file_actions::journal_line::JournalEntry;
use pr_core::file_actions::service::FileActionService;
use pr_core::file_actions::types::{
    CaptureGroupActionRequest, CaptureGroupActionResult, FileActionRequest, FileActionResult,
};
use pr_core::file_actions::undo::MoveOverride;
use pr_core::model::FileOperationType;
use pr_core::sync::CancelToken;
use pr_core::time::{DateTimeUtc, TICKS_PER_SECOND};
use pr_test_support::{FakeClock, FakeFileSystem, golden};
use serde_json::{Value, json};

/// The shared hook trace of one case (the oracle's `trace` list).
type Trace = Arc<Mutex<Vec<String>>>;

/// Parsed `faults` object of one case. Keys are lower-cased paths (OrdinalIgnoreCase).
#[derive(Default, Clone)]
struct Faults {
    no_bin_roots: Vec<String>,
    bin_capacity: Vec<(String, u64)>,
    move_fail: HashMap<String, String>,
    move_leaves_source: HashSet<String>,
    move_truncate: HashMap<String, usize>,
    copy_partial: HashMap<String, (usize, String)>,
    copy_fail: HashMap<String, String>,
    copy_size: HashMap<String, usize>,
    foreign_on_copy: HashMap<String, usize>,
    copy_then_cancel: HashSet<String>,
    recycle_fail: HashMap<String, String>,
    recycle_leaves: HashSet<String>,
    permanent_leaves: HashSet<String>,
    permanent_fail: HashMap<String, String>,
    delete_fail: HashMap<String, String>,
    append_fail: HashSet<usize>,
    move_round_2s: bool,
    cancel_on: Option<(String, String)>,
}

fn key(path: &str) -> String {
    path.to_ascii_lowercase()
}

/// Reads the `faults` object (absent => no faults).
fn parse_faults(case: &Value) -> Faults {
    let mut faults = Faults::default();
    let Some(object) = case.get("faults").and_then(Value::as_object) else {
        return faults;
    };
    let strings = |v: &Value| -> Vec<String> {
        v.as_array()
            .map(|a| a.iter().filter_map(Value::as_str).map(str::to_owned).collect())
            .unwrap_or_default()
    };
    let messages = |v: &Value| -> HashMap<String, String> {
        v.as_object()
            .map(|o| {
                o.iter()
                    .map(|(p, m)| (key(p), m.as_str().unwrap_or_default().to_owned()))
                    .collect()
            })
            .unwrap_or_default()
    };
    for (name, value) in object {
        match name.as_str() {
            "no_bin_roots" => faults.no_bin_roots = strings(value),
            "bin_capacity" => {
                faults.bin_capacity = value
                    .as_object()
                    .map(|o| o.iter().map(|(r, b)| (r.clone(), b.as_u64().unwrap_or(0))).collect())
                    .unwrap_or_default()
            }
            "move_fail" => faults.move_fail = messages(value),
            "move_leaves_source" => faults.move_leaves_source = strings(value).iter().map(|p| key(p)).collect(),
            "move_truncate" => {
                faults.move_truncate = value
                    .as_object()
                    .map(|o| {
                        o.iter()
                            .map(|(p, n)| (key(p), n.as_u64().unwrap_or(0) as usize))
                            .collect()
                    })
                    .unwrap_or_default()
            }
            "copy_partial" => {
                faults.copy_partial = value
                    .as_object()
                    .map(|o| {
                        o.iter()
                            .map(|(p, v)| {
                                (
                                    key(p),
                                    (
                                        v["bytes"].as_u64().unwrap_or(0) as usize,
                                        v["message"].as_str().unwrap_or_default().to_owned(),
                                    ),
                                )
                            })
                            .collect()
                    })
                    .unwrap_or_default()
            }
            "copy_fail" => faults.copy_fail = messages(value),
            "copy_size" | "foreign_on_copy" => {
                let map: HashMap<String, usize> = value
                    .as_object()
                    .map(|o| {
                        o.iter()
                            .map(|(p, n)| (key(p), n.as_u64().unwrap_or(0) as usize))
                            .collect()
                    })
                    .unwrap_or_default();
                if name == "copy_size" {
                    faults.copy_size = map;
                } else {
                    faults.foreign_on_copy = map;
                }
            }
            "copy_then_cancel" => faults.copy_then_cancel = strings(value).iter().map(|p| key(p)).collect(),
            "recycle_fail" => faults.recycle_fail = messages(value),
            "recycle_leaves" => faults.recycle_leaves = strings(value).iter().map(|p| key(p)).collect(),
            "permanent_leaves" => faults.permanent_leaves = strings(value).iter().map(|p| key(p)).collect(),
            "permanent_fail" => faults.permanent_fail = messages(value),
            "delete_fail" => faults.delete_fail = messages(value),
            "append_fail" => {
                faults.append_fail = value
                    .as_array()
                    .map(|a| a.iter().filter_map(Value::as_u64).map(|n| n as usize).collect())
                    .unwrap_or_default()
            }
            "move_round_2s" => faults.move_round_2s = value.as_bool().unwrap_or(false),
            "cancel_on" => {
                faults.cancel_on = Some((
                    value["op"].as_str().unwrap_or_default().to_owned(),
                    value["path"].as_str().unwrap_or_default().to_owned(),
                ))
            }
            other => panic!("golden fault key not handled by the harness: {other}"),
        }
    }
    faults
}

/// The oracle's `W304Disk`: the fake disk with the case's faults, tracing every mutating call.
struct ScenarioFs {
    disk: Arc<FakeFileSystem>,
    trace: Trace,
    faults: Faults,
    cancel: CancelToken,
    journal_appends: Mutex<usize>,
}

impl ScenarioFs {
    /// Records the call (C# `Trace`) and cancels the token first when `cancel_on` names it.
    fn traced(&self, op: &str, path: &str) {
        self.trace.lock().expect("trace").push(format!("{op}:{path}"));
        if let Some((cancel_op, cancel_path)) = &self.faults.cancel_on {
            if cancel_op == op && key(cancel_path) == key(path) {
                self.cancel.cancel();
            }
        }
    }

    fn copy_into(
        &self,
        source: &Path,
        destination: &Path,
        proof: Option<&pr_core::abstractions::CopyCreationProof>,
    ) -> io::Result<()> {
        let src = source.to_string_lossy().into_owned();
        self.traced("copy", &src);
        if let Some(message) = self.faults.copy_fail.get(&key(&src)) {
            return Err(io::Error::other(message.clone()));
        }
        if let Some(bytes) = self.faults.foreign_on_copy.get(&key(&src)) {
            self.disk.add_file_at(
                destination,
                &pattern_bytes(*bytes),
                stamp(common_file_actions::LAST_WRITE_TICKS),
            );
            return Err(io::Error::new(
                io::ErrorKind::AlreadyExists,
                format!("The file '{}' already exists.", destination.display()),
            ));
        }
        let created = |p: &pr_core::abstractions::CopyCreationProof| p.mark_created();
        if let Some((bytes, message)) = self.faults.copy_partial.get(&key(&src)) {
            self.disk.add_file_at(
                destination,
                &pattern_bytes(*bytes),
                stamp(common_file_actions::LAST_WRITE_TICKS),
            );
            if let Some(p) = proof {
                created(p);
            }
            return Err(io::Error::other(message.clone()));
        }
        if let Some(bytes) = self.faults.copy_size.get(&key(&src)) {
            self.disk.add_file_at(
                destination,
                &pattern_bytes(*bytes),
                stamp(common_file_actions::LAST_WRITE_TICKS),
            );
            if let Some(p) = proof {
                created(p);
            }
            return Ok(());
        }
        self.disk.copy_file(source, destination)?;
        if let Some(p) = proof {
            created(p);
        }
        if self.faults.copy_then_cancel.contains(&key(&src)) {
            self.cancel.cancel();
        }
        Ok(())
    }
}

impl FileSystem for ScenarioFs {
    fn file_exists(&self, path: &Path) -> bool {
        self.disk.file_exists(path)
    }

    fn directory_exists(&self, path: &Path) -> bool {
        self.disk.directory_exists(path)
    }

    fn get_file_stat(&self, path: &Path) -> Option<FileStat> {
        self.disk.get_file_stat(path)
    }

    fn move_file(&self, source: &Path, destination: &Path) -> io::Result<()> {
        let src = source.to_string_lossy().into_owned();
        self.traced("move", &src);
        if let Some(message) = self.faults.move_fail.get(&key(&src)) {
            return Err(io::Error::other(message.clone()));
        }
        if self.faults.move_leaves_source.contains(&key(&src)) {
            return self.disk.copy_file(source, destination);
        }
        self.disk.move_file(source, destination)?;
        if let Some(length) = self.faults.move_truncate.get(&key(&src)) {
            let stat = self.disk.peek_stat(destination).expect("moved file exists");
            self.disk
                .add_file_at(destination, &pattern_bytes(*length), stat.last_write_utc);
        }
        if self.faults.move_round_2s {
            if let Some(stat) = self.disk.peek_stat(destination) {
                let even = 2 * TICKS_PER_SECOND;
                let floored = stat.last_write_utc.ticks() - stat.last_write_utc.ticks() % even;
                self.disk.set_last_write(destination, stamp(floored));
            }
        }
        Ok(())
    }

    fn copy_file(&self, source: &Path, destination: &Path) -> io::Result<()> {
        self.copy_into(source, destination, None)
    }

    fn try_copy_new_with_proof(
        &self,
        source: &Path,
        destination: &Path,
        proof: &pr_core::abstractions::CopyCreationProof,
    ) -> io::Result<bool> {
        if self.disk.file_exists(destination) {
            return Err(io::Error::new(
                io::ErrorKind::AlreadyExists,
                format!("The file '{}' already exists.", destination.display()),
            ));
        }
        self.copy_into(source, destination, Some(proof))?;
        Ok(true)
    }

    fn delete(&self, path: &Path) -> io::Result<()> {
        let p = path.to_string_lossy().into_owned();
        self.traced("delete", &p);
        if let Some(message) = self.faults.delete_fail.get(&key(&p)) {
            return Err(io::Error::other(message.clone()));
        }
        self.disk.delete(path)
    }

    fn open_read_shared(&self, path: &Path, buffer_size: usize) -> io::Result<Box<dyn ReadSeek>> {
        self.disk.open_read_shared(path, buffer_size)
    }

    fn open_append(&self, path: &Path, durable: bool) -> io::Result<Box<dyn AppendStream>> {
        if path.to_string_lossy().eq_ignore_ascii_case(&journal_path()) {
            self.trace.lock().expect("trace").push("append".to_owned());
            let mut count = self.journal_appends.lock().expect("count");
            *count += 1;
            if self.faults.append_fail.contains(&*count) {
                return Err(io::Error::other("journal unavailable"));
            }
        }
        self.disk.open_append(path, durable)
    }

    fn write_all_text_atomic(&self, path: &Path, text: &str, durable: bool) -> io::Result<()> {
        self.disk.write_all_text_atomic(path, text, durable)
    }

    fn read_all_text(&self, path: &Path) -> io::Result<String> {
        self.disk.read_all_text(path)
    }

    fn enumerate_files(&self, directory: &Path, pattern: &str) -> io::Result<Vec<PathBuf>> {
        self.disk.enumerate_files(directory, pattern)
    }

    fn enumerate_directories(&self, directory: &Path) -> io::Result<Vec<PathBuf>> {
        self.disk.enumerate_directories(directory)
    }

    fn create_directory(&self, path: &Path) -> io::Result<()> {
        self.traced("mkdir", &path.to_string_lossy());
        self.disk.create_directory(path)
    }

    fn try_delete_empty_directory(&self, path: &Path) -> bool {
        self.trace
            .lock()
            .expect("trace")
            .push(format!("rmdir:{}", path.to_string_lossy()));
        self.disk.try_delete_empty_directory(path)
    }
}

/// The oracle's `W304Bin`: [`ScenarioBin`] plus the shared trace and the `cancel_on` hook.
struct GoldenBin {
    inner: Arc<ScenarioBin>,
    trace: Trace,
    faults: Arc<Faults>,
    cancel: CancelToken,
}

impl GoldenBin {
    fn traced(&self, op: &str, path: &Path) {
        let p = path.to_string_lossy().into_owned();
        self.trace.lock().expect("trace").push(format!("{op}:{p}"));
        if let Some((cancel_op, cancel_path)) = &self.faults.cancel_on {
            if cancel_op == op && key(cancel_path) == key(&p) {
                self.cancel.cancel();
            }
        }
    }
}

impl RecycleBin for GoldenBin {
    fn send_to_recycle_bin(&self, path: &Path) -> io::Result<()> {
        self.traced("recycle", path);
        self.inner.send_to_recycle_bin(path)
    }

    fn can_recycle(&self, path: &Path) -> bool {
        self.inner.can_recycle(path)
    }

    fn delete_permanently(&self, path: &Path) -> io::Result<()> {
        self.traced("permanent", path);
        self.inner.delete_permanently(path)
    }

    fn try_restore(
        &self,
        original_path: &Path,
        expected_size: u64,
        expected_last_write_utc: DateTimeUtc,
    ) -> io::Result<bool> {
        self.inner
            .try_restore(original_path, expected_size, expected_last_write_utc)
    }

    fn fits_in_recycle_bin(&self, path: &Path, file_size: u64) -> bool {
        self.inner.fits_in_recycle_bin(path, file_size)
    }
}

/// C# `FileOperationType` name of the golden `op` string.
fn op_of(name: &str) -> FileOperationType {
    match name {
        "Move" => FileOperationType::Move,
        "Copy" => FileOperationType::Copy,
        "Recycle" => FileOperationType::Recycle,
        other => panic!("unknown golden op {other}"),
    }
}

/// Replaces each 32-hex GUID with `<idN>`, numbering in order of first appearance (the golden normalization).
fn normalize_ids(text: &str, seen: &mut Vec<String>) -> String {
    let bytes = text.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let is_guid = i + 32 <= bytes.len()
            && bytes[i..i + 32]
                .iter()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(b))
            && (i == 0 || !bytes[i - 1].is_ascii_alphanumeric())
            && (i + 32 == bytes.len() || !bytes[i + 32].is_ascii_alphanumeric());
        if is_guid {
            let guid = text[i..i + 32].to_owned();
            let index = match seen.iter().position(|g| *g == guid) {
                Some(index) => index,
                None => {
                    seen.push(guid);
                    seen.len() - 1
                }
            };
            out.push_str(&format!("<id{}>", index + 1));
            i += 32;
        } else {
            let ch = text[i..].chars().next().expect("char boundary");
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

fn opt(text: &Option<String>) -> Value {
    text.as_ref().map_or(Value::Null, |s| json!(s))
}

/// Runs one golden case and returns its observed values in the golden's shape.
fn run_case(case: &Value) -> Value {
    let clock = Arc::new(FakeClock::at(stamp(CLOCK_TICKS)));
    let disk = Arc::new(FakeFileSystem::with_clock(clock.clone()));
    for file in case["files"].as_array().expect("files") {
        let ticks: i64 = file["ticks"]
            .as_str()
            .expect("ticks text")
            .parse()
            .expect("ticks number");
        let bytes = file["bytes"].as_u64().expect("bytes") as usize;
        disk.add_file_at(
            file["path"].as_str().expect("path"),
            &pattern_bytes(bytes),
            stamp(ticks),
        );
    }
    for dir in case.get("dirs").and_then(Value::as_array).into_iter().flatten() {
        disk.add_dir(dir.as_str().expect("dir"));
    }
    let faults = parse_faults(case);
    let trace: Trace = Arc::new(Mutex::new(Vec::new()));
    let cancel = CancelToken::new();
    if case.get("pre_cancelled").and_then(Value::as_bool).unwrap_or(false) {
        cancel.cancel();
    }
    let fs = Arc::new(ScenarioFs {
        disk: disk.clone(),
        trace: trace.clone(),
        faults: faults.clone(),
        cancel: cancel.clone(),
        journal_appends: Mutex::new(0),
    });
    let inner_bin = Arc::new(ScenarioBin::new(disk.clone()));
    inner_bin.set_no_bin_roots(&faults.no_bin_roots.iter().map(String::as_str).collect::<Vec<_>>());
    for (root, bytes) in &faults.bin_capacity {
        inner_bin.set_capacity(root, *bytes);
    }
    for (path, message) in &faults.recycle_fail {
        inner_bin.fail_send(path, message);
    }
    for path in &faults.recycle_leaves {
        inner_bin.leave_on_send(path);
    }
    for (path, message) in &faults.permanent_fail {
        inner_bin.fail_permanent(path, message);
    }
    for path in &faults.permanent_leaves {
        inner_bin.leave_on_permanent(path);
    }
    let bin = Arc::new(GoldenBin {
        inner: inner_bin.clone(),
        trace: trace.clone(),
        faults: Arc::new(faults.clone()),
        cancel: cancel.clone(),
    });

    let fs_dyn: Arc<dyn FileSystem> = fs.clone();
    let clock_dyn: Arc<dyn Clock> = clock.clone();
    let journal = Arc::new(OperationJournal::with_options(
        &fixture_paths(),
        fs_dyn.clone(),
        clock_dyn.clone(),
        OperationJournalOptions::default(),
    ));
    let mut service = FileActionService::new(journal.clone(), fs_dyn, clock_dyn, bin.clone());
    if let Some(mode) = case["move_override"].as_str() {
        let disk_for_override = disk.clone();
        let mode = mode.to_owned();
        let override_fn: MoveOverride = Arc::new(move |source: &Path, destination: &Path| {
            disk_for_override.move_file(source, destination)?;
            match mode.as_str() {
                "move-then-fail" => Err(io::Error::other("override failed after the move")),
                "move-then-cancel" => Err(canceled_error()),
                other => panic!("unknown move_override {other}"),
            }
        });
        service = service.with_move_override(override_fn);
    }

    let request = &case["request"];
    let result_json = if request["kind"] == "single" {
        let mut req = FileActionRequest::new(
            request["source"].as_str().expect("source"),
            op_of(request["op"].as_str().expect("op")),
        );
        req.destination = request["destination"].as_str().map(str::to_owned);
        req.allow_permanent_delete = request["allow_permanent"].as_bool().unwrap_or(false);
        let result: FileActionResult = service.execute(&req, &cancel);
        single_result_json(&result)
    } else {
        let capture = CaptureGroup::new(
            request["jpeg"].as_str().expect("jpeg"),
            request["raw"].as_str().expect("raw"),
            request["xmp"].as_str().map(str::to_owned),
        )
        .expect("golden group is valid");
        let mut req = CaptureGroupActionRequest::new(capture, op_of(request["op"].as_str().expect("op")));
        req.destination = request["destination"].as_str().map(str::to_owned);
        req.allow_permanent_delete = request["allow_permanent"].as_bool().unwrap_or(false);
        let result: CaptureGroupActionResult = service.execute_group(&req, &cancel);
        group_result_json(&result)
    };

    // Observations after the action, in the golden's shape.
    let mut seen_ids: Vec<String> = Vec::new();
    let journal_text = disk
        .file_content(Path::new(&journal_path()))
        .map(|b| String::from_utf8(b).expect("UTF-8 journal"))
        .unwrap_or_default();
    let journal_lines: Vec<String> = journal_text
        .split("\r\n")
        .filter(|l| !l.is_empty())
        .map(|l| normalize_ids(l, &mut seen_ids))
        .collect();
    let mut result_json = result_json;
    normalize_result_ids(&mut result_json, &mut seen_ids);

    let mut files_after: Vec<(String, u64, i64)> = disk
        .all_files()
        .into_iter()
        .filter(|p| !p.to_string_lossy().eq_ignore_ascii_case(&journal_path()))
        .filter_map(|p| {
            disk.peek_stat(&p)
                .map(|s| (p.to_string_lossy().into_owned(), s.length, s.last_write_utc.ticks()))
        })
        .collect();
    files_after.sort_by_key(|(p, _, _)| p.to_ascii_lowercase());
    let files_after: Vec<Value> = files_after
        .into_iter()
        .map(|(p, len, ticks)| json!({"path": p, "size": len, "ticks": ticks.to_string()}))
        .collect();
    let dirs_after: Vec<Value> = case
        .get("probe_dirs")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|d| {
            let path = d.as_str().expect("probe dir");
            json!({"path": path, "exists": disk.directory_exists(Path::new(path))})
        })
        .collect();

    json!({
        "result": result_json,
        "journal_lines": journal_lines,
        "journal_ends_with_crlf": journal_text.is_empty() || journal_text.ends_with("\r\n"),
        "files_after": files_after,
        "dirs_after": dirs_after,
        "recycled": inner_bin.recycled(),
        "permanently_deleted_paths": inner_bin.permanently_deleted(),
        "fits_calls": inner_bin.fits_calls(),
        "trace": trace.lock().expect("trace").clone(),
        "busy_after": service.is_busy(),
        "token_cancelled": cancel.is_canceled(),
    })
}

fn single_result_json(r: &FileActionResult) -> Value {
    json!({
        "succeeded": r.succeeded,
        "rejected": r.rejected,
        "operation": format!("{:?}", r.operation),
        "source": r.source,
        "destination_path": opt(&r.destination_path),
        "size": r.size,
        "last_write_ticks": r.last_write_utc.ticks().to_string(),
        "error": opt(&r.error),
        "journal_persisted": r.journal_persisted,
        "journal_error": opt(&r.journal_error),
        "permanently_deleted": r.permanently_deleted,
        "source_removed": r.source_removed,
    })
}

fn group_result_json(r: &CaptureGroupActionResult) -> Value {
    let members: Vec<Value> = r
        .members
        .iter()
        .map(|m| {
            json!({
                "source": m.member.source,
                "destination": opt(&m.member.destination),
                "size": m.member.size,
                "last_write_ticks": m.member.last_write_utc.value.ticks().to_string(),
                "permanent": m.member.permanent,
                "completed": m.completed,
                "conflict": m.conflict,
                "error": opt(&m.error),
                "source_exists": m.source_exists,
                "destination_exists": m.destination_exists,
                "state_known": m.state_known,
            })
        })
        .collect();
    json!({
        "succeeded": r.succeeded,
        "rejected": r.rejected,
        "operation": format!("{:?}", r.operation),
        "group_id": r.group_id,
        "entry": r.entry.as_ref().map_or(Value::Null, |e| entry_json_raw(e)),
        "members": members,
        "error": opt(&r.error),
        "journal_persisted": r.journal_persisted,
        "journal_error": opt(&r.journal_error),
        "permanently_deleted": r.permanently_deleted,
        "skipped_missing": r.skipped_missing.as_ref().map_or(Value::Null, |v| json!(v)),
    })
}

/// The entry without id normalization (normalized later together with the rest of the result).
fn entry_json_raw(entry: &JournalEntry) -> Value {
    json!({
        "id": entry.id,
        "state": format!("{:?}", entry.state),
        "source": entry.source,
        "destination": opt(&entry.destination),
        "error": opt(&entry.error),
        "error_code": opt(&entry.error_code),
        "permanent": entry.permanent.map_or(Value::Null, |p| json!(p)),
        "group_id": entry.group_id.clone().map_or(Value::Null, |g| json!(g)),
        "member_count": entry.group_members.as_ref().map_or(Value::Null, |m| json!(m.len())),
    })
}

/// Normalizes the GUIDs of a group result in the golden's order: `group_id`, then `entry.id`, `entry.group_id`.
fn normalize_result_ids(result: &mut Value, seen: &mut Vec<String>) {
    if let Some(group_id) = result.get("group_id").and_then(Value::as_str).map(str::to_owned) {
        result["group_id"] = json!(normalize_ids(&group_id, seen));
    }
    if let Some(entry) = result.get_mut("entry").and_then(Value::as_object_mut) {
        if let Some(id) = entry.get("id").and_then(Value::as_str).map(str::to_owned) {
            entry.insert("id".to_owned(), json!(normalize_ids(&id, seen)));
        }
        if let Some(group) = entry.get("group_id").and_then(Value::as_str).map(str::to_owned) {
            entry.insert("group_id".to_owned(), json!(normalize_ids(&group, seen)));
        }
    }
}

/// Every golden case, one after another: the first mismatch names the case and the field.
#[test]
fn file_action_scenarios_golden_all_cases_match_the_oracle() {
    let golden = golden::load("file-action-scenarios");
    assert_eq!(
        golden.cases.len(),
        111,
        "the golden has 111 cases (56 single, 55 group)"
    );
    let mut mismatches: Vec<String> = Vec::new();
    for case in &golden.cases {
        let name = case["name"].as_str().expect("case name");
        let observed = run_case(case);
        let expected = &case["expected"];
        for field in [
            "result",
            "journal_lines",
            "journal_ends_with_crlf",
            "files_after",
            "dirs_after",
            "recycled",
            "permanently_deleted_paths",
            "fits_calls",
            "trace",
            "busy_after",
            "token_cancelled",
        ] {
            if observed.get(field) != expected.get(field) {
                mismatches.push(format!(
                    "{name}: {field}\n  expected {}\n  observed {}",
                    expected.get(field).map_or_else(String::new, |v| v.to_string()),
                    observed.get(field).map_or_else(String::new, |v| v.to_string())
                ));
            }
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} golden field(s) differ:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
